use actix_web::{post, web, App, HttpServer, HttpResponse, Responder};
use serde_json::Value;

#[post("/users")]
async fn create_user(body: web::Json<Value>) -> impl Responder {
    let username = body["username"].as_str().unwrap().to_string();
    HttpResponse::Created().json(serde_json::json!({"username": username}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| App::new().service(create_user))
        .bind(("0.0.0.0", 8043))?
        .run()
        .await
}

