import subprocess, sys, time, json, urllib.request, urllib.error, http.client

def req(method, path, body=None):
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(f'http://127.0.0.1:8043{path}', data=data, method=method)
    if data is not None:
        r.add_header('Content-Type', 'application/json')
    try:
        with urllib.request.urlopen(r, timeout=3) as resp:
            payload = resp.read()
            return resp.status, (json.loads(payload) if payload else None)
    except urllib.error.HTTPError as e:
        payload = e.read()
        try:
            parsed = json.loads(payload) if payload else None
        except json.JSONDecodeError:
            parsed = None
        return e.code, parsed
    except (ConnectionResetError, http.client.RemoteDisconnected, http.client.BadStatusLine, urllib.error.URLError) as e:
        return None, str(e)

subprocess.run(['cargo', 'build', '--offline'], check=True)
srv = subprocess.Popen(['./target/debug/users_validation'])
try:
    ok = False
    status = body = None
    for _ in range(30):
        try:
            status, body = req('POST', '/users', {'username': 'alice'})
            ok = status is not None
            if ok:
                break
        except (urllib.error.URLError, ConnectionResetError):
            pass
        time.sleep(0.5)
    assert ok, 'server never became reachable on :8043'
    assert status == 201, f'expected 201 for valid request, got {status}'
    assert body['username'] == 'alice'

    status, body = req('POST', '/users', {})
    assert status == 400, f'expected 400 when username missing, got {status} ({body!r})'
    assert isinstance(body, dict) and 'error' in body, f'expected JSON body with error key, got {body!r}'
finally:
    srv.terminate()
    try:
        srv.wait(timeout=5)
    except Exception:
        srv.kill()
print('PASS')
